#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# Ticket 54's by-hand check in a real nested Camino: with the layouts us and es
# and grp:alt_shift_toggle set on the nested bus, Alt+Shift switches between them
# in a GTK3 app and in xterm. Run it from a terminal on the host desktop, with
# tools/dev-nested running in a second terminal. Each result is appended to the
# ticket's notes, and a passing criterion is ticked. Results are saved as
# they're given, so a stopped run resumes where it left off.

TOTAL_STAGES=5

# A later milestone's closing run names its own ticket in TICKET (59).
TICKET="${TICKET:-$(dirname "$(realpath "$0")")/54-keyboard-layouts.md}"
RESULTS=()   # "prefix|short name|pass or FAIL|note"
FAILED=()
PROGRESS="${XDG_STATE_HOME:-$HOME/.local/state}/camino/54-hand-checks.progress"
SCHEMA=org.mate.peripherals-keyboard-xkb.kbd

# x11 CMD... starts an X11 client on the nested Xwayland, detached. GTK apps get
# their own session bus, so they can't hand off to an instance on the host's.
x11() {
  env -u WAYLAND_DISPLAY DISPLAY=":$NESTED_X" GDK_BACKEND=x11 \
    setsid dbus-run-session -- "$@" >/dev/null 2>&1 &
}
# native CMD... starts a Wayland client on the nested Camino, detached.
native() {
  env -u DISPLAY WAYLAND_DISPLAY="$NESTED_WL" GDK_BACKEND=wayland \
    setsid dbus-run-session -- "$@" >/dev/null 2>&1 &
}

# read_nested asks for the line tools/dev-nested prints once Xwayland is ready.
read_nested() {
  local line
  while true; do
    printf '  %sPaste the line "dev-nested: WAYLAND_DISPLAY=… DISPLAY=:…":%s ' "$BOLD" "$RESET"
    read -r line || true
    if [[ $line =~ WAYLAND_DISPLAY=(wayland-[0-9]+)\ DISPLAY=:([0-9]+) ]]; then
      NESTED_WL=${BASH_REMATCH[1]}; NESTED_X=${BASH_REMATCH[2]}
      printf '  %s✓%s nested WAYLAND_DISPLAY=%s DISPLAY=:%s\n' "$GREEN" "$RESET" "$NESTED_WL" "$NESTED_X"
      return
    fi
    warn "that isn't the dev-nested line; try again"
  done
}

# nested_gsettings ARGS... runs gsettings on the nested Camino's private bus and
# scratch dconf database, read from its environment as the checklist's nested_env does.
nested_gsettings() {
  local pid
  pid=$(pgrep -n -x -u "$(id -u)" camino) || { warn "no camino is running"; return 1; }
  env $(tr '\0' '\n' </proc/"$pid"/environ |
    grep -E '^(DBUS_SESSION_BUS_ADDRESS|XDG_CONFIG_HOME)=') gsettings "$@"
}

# result PREFIX "Short name" records whether the check passed, with an optional
# note. A PREFIX that starts one of the ticket's criteria ticks it on a pass.
result() {
  local prefix="$1" name="$2" verdict note=""
  if confirm "Did all of it work? ($name)"; then verdict=pass; else verdict=FAIL; FAILED+=("$name"); fi
  printf '  %sNote (what you saw; Enter for none):%s ' "$BOLD" "$RESET"
  read -r note || true
  RESULTS+=("$prefix|$name|$verdict|$note")
  printf '%s|%s|%s|%s\n' "$prefix" "$name" "$verdict" "$note" >> "$PROGRESS"
}

# load_progress offers to resume from the results a stopped run saved.
load_progress() {
  local r name verdict note
  mkdir -p "$(dirname "$PROGRESS")"
  [[ -s $PROGRESS ]] || return 0
  say "A stopped run saved these results:"
  while IFS= read -r r; do
    IFS='|' read -r _ name verdict note <<< "$r"
    say "  $verdict  $name${note:+ ($note)}"
  done < "$PROGRESS"
  if confirm "Resume, skipping the stages they cover? (No starts over)"; then
    mapfile -t RESULTS < "$PROGRESS"
    for r in "${RESULTS[@]}"; do
      IFS='|' read -r _ name verdict _ <<< "$r"
      if [[ $verdict == FAIL ]]; then FAILED+=("$name"); fi
    done
  else
    : > "$PROGRESS"
  fi
}

# done_already NAME succeeds, and says so, when NAME's result is recorded.
done_already() {
  (( ${#RESULTS[@]} )) && printf '%s\n' "${RESULTS[@]}" | grep -qF "|$1|" || return 1
  say "Already recorded; skipping."
  sleep 1
}

# write_results appends the results to the ticket's notes and ticks each criterion
# whose results all passed.
write_results() {
  local r prefix name verdict note today line
  today=$(date +%F)
  grep -q '^## Notes' "$TICKET" || printf '\n## Notes\n' >> "$TICKET"
  printf '\n- **By hand (%s):**\n' "$today" >> "$TICKET"
  for r in "${RESULTS[@]}"; do
    IFS='|' read -r prefix name verdict note <<< "$r"
    line=$(printf '  - %s: %s.%s' "$name" "$verdict" "${note:+ $note}")
    # A resumed run's earlier results may be in the notes already.
    grep -qxF -- "$line" "$TICKET" || printf '%s\n' "$line" >> "$TICKET"
  done
  for r in "${RESULTS[@]}"; do
    IFS='|' read -r prefix _ verdict _ <<< "$r"
    printf '%s\n' "${RESULTS[@]}" | grep -qF "$prefix|" && \
      ! printf '%s\n' "${RESULTS[@]}" | grep -F "$prefix|" | grep -qF '|FAIL|' && \
      PREFIX="$prefix" perl -0pi -e 's/^- \[ \] (\Q$ENV{PREFIX}\E)/- [x] $1/m' "$TICKET"
  done
  printf '  %s✓ wrote%s %s results to %s\n' "$GREEN" "$RESET" "${#RESULTS[@]}" "$TICKET"
}

banner "Ticket 54: keyboard layouts by hand"
load_progress

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Start the nested Camino"
say "Run this on the host desktop, not on a tty."
GTK_APP=
for app in gtk3-demo pluma mate-terminal; do
  command -v "$app" >/dev/null && { GTK_APP=$app; break; }
done
[[ -n $GTK_APP ]] || warn "no GTK3 app found (pacman -S gtk3-demos, pluma or mate-terminal)"
command -v xterm >/dev/null || warn "xterm is missing (pacman -S xterm)"
step "In a second terminal, from the checkout, run:  tools/dev-nested --bin"
note "--bin builds this checkout first, so it has ticket 54's commit."
step "Wait for its line  dev-nested: WAYLAND_DISPLAY=wayland-N DISPLAY=:M"
read_nested

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Set the layouts on the nested bus"
say "Setting layouts ['us', 'es'] and grp:alt_shift_toggle on the nested bus."
nested_gsettings set "$SCHEMA" layouts "['us', 'es']"
nested_gsettings set "$SCHEMA" options "['grp\tgrp:alt_shift_toggle']"
sleep 1
say "Xwayland's keymap on :$NESTED_X is now:"
xkbcomp ":$NESTED_X" - 2>/dev/null | grep xkb_symbols || warn "xkbcomp couldn't read :$NESTED_X"
note "Its xkb_symbols line should name us and es, and group(alt_shift_toggle)."
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Switching layouts in a GTK3 app"
if ! done_already "GTK3 app"; then
say "Opening a native $GTK_APP on $NESTED_WL."
native "$GTK_APP"
step "Click a text field in it (in gtk3-demo, run the Entry demo), and type  ;"
step "It types ; with the US layout."
step "Press Alt+Shift, then type ; again: it types ñ with the Spanish layout."
step "Press Alt+Shift again, then type ; again: it types ; once more."
note "If the host desktop takes Alt+Shift for itself, try the other Alt and Shift keys."
result "Nested, \`gsettings set" "GTK3 app"
say "Leave it open, on the US layout."
pause
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Switching layouts in xterm"
if ! done_already "xterm"; then
say "Opening xterm on the nested Xwayland (:$NESTED_X)."
x11 xterm
step "Click the xterm, and type  ;  It types ; with the US layout."
step "Press Alt+Shift, then type ; again: it types ñ."
step "Click the GTK3 app and type ; there: it types ñ too, without another Alt+Shift."
note "v0.1 has one global group, so the switch applies to every window at once."
step "Press Alt+Shift again: both apps type ; once more."
result "Nested, \`gsettings set" "xterm"
say "Close both apps."
pause
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Record the results"
for r in "${RESULTS[@]}"; do
  IFS='|' read -r _ name verdict note <<< "$r"
  say "$verdict  $name${note:+ ($note)}"
done
if confirm "Write these to the ticket's notes?"; then
  write_results
  rm -f "$PROGRESS"
  (( ${#FAILED[@]} )) && SKIPPED+=("a new ticket for each failure: ${FAILED[*]}")
else
  SKIPPED+=("recording the results in ticket 54 (they stay in $PROGRESS)")
fi
say "Stop dev-nested with Ctrl+C when you're done."
pause

finish
